INSERT INTO templates (
    template_name
    , description
    , thumbnail_url
    , html_content
    , css_content
    , is_public
    , created_by
    , use_yn
    , created_at
    , updated_at
) VALUES (
    #{templateName}
    , #{description}
    , #{thumbnailUrl}
    , #{htmlContent}
    , #{cssContent}
    , #{isPublic}
    , #{createdBy}
    , 'Y'
    , CURRENT_TIMESTAMP
    , CURRENT_TIMESTAMP
)
